/**
 * Schema manifest DSL.
 *
 * This package intentionally has **no third-party schema dependency** (the build
 * environment is offline; `drizzle-orm` cannot be installed here). `TABLES` is a
 * typed, framework-neutral manifest that is the single source for:
 *   - `drizzle/0001_init.sql` (generated by `node scripts/generate.mjs`)
 *   - the seed program (types/columns reuse)
 *   - a future Drizzle adapter (`adapter-drizzle.ts`) 1:1 mapped from this manifest.
 *
 * Column line grammar:
 *   "<snake_name> <type> [nn] [pk] [uq] [def:<sql literal>] [fk:<table>] [pd:<action>]"
 * Types: bigint | int | smallint | varchar(n) | char(n) | text | uuid | timestamptz |
 *        date | boolean | numeric(p,s) | jsonb | inet | bytea
 *
 * Standard column block (ADR-0003) is appended automatically unless `noStd`:
 *   id, public_id, created_at, updated_at, created_by, updated_by, version
 * `append: true` omits version/updated_by (append-only), `softDel: true` adds deleted_at.
 */

declare const spec: unique symbol;
export type TableSpec = {
  name: string;
  doc: string;
  cols: string[];
  uq?: string[][];
  ix?: string[][];
  ck?: [string, string][];
  append?: boolean;
  softDel?: boolean;
  partition?: 'created_at';
  noStd?: boolean;
  [spec]?: never;
};

const t = (s: TableSpec): TableSpec => s;

